from pypdf import PdfReader
import json, pathlib, html
p=pathlib.Path(__file__).parent
d=PdfReader(r'C:\Users\Екатерина\Downloads\Спринт_3_Territory_automation_обновленная_презентация.pptx.pdf')
titles=['Интеллектуальный ассистент УК','Почему процесс требует изменений','Новая архитектура ассистента','От документации до задач в CRM','Потенциал на объёме заказчика','Проверка перед масштабированием','Знания о процессе — ключ к качеству','Агент находит. Инженер подтверждает.','Команда проекта']
pages=[1,3,6,7,9,10,11,12,16]
sections=[]
for n,(page,title) in enumerate(zip(pages,titles)):
 text=d.pages[page-1].extract_text()
 lines=[x.strip() for x in text.splitlines() if x.strip()]
 sections.append('<section class="slide '+('active' if n==0 else '')+'"><div class="eyebrow">TERRITORY AUTOMATION <span>Спринт 03 / '+str(n+1).zfill(2)+'</span></div><h1>'+html.escape(title)+'</h1><div class="content">'+''.join('<p>'+html.escape(x)+'</p>' for x in lines)+'</div><div class="orb"></div></section>')
css='''*{box-sizing:border-box}body{margin:0;background:#edf2f8;color:#142a4b;font-family:Aptos,"Segoe UI",sans-serif;overflow:hidden}.slide{position:absolute;inset:0;padding:5vh 7vw 10vh;opacity:0;transform:translateX(45px);pointer-events:none;transition:opacity .65s,transform .65s;background:radial-gradient(ellipse at 95% 0%,#cedfff,transparent 55%),linear-gradient(130deg,#fff,#eef2f7)}.slide.active{opacity:1;transform:none;pointer-events:auto}.eyebrow{font-size:12px;letter-spacing:3px;color:#3668ac;display:flex;justify-content:space-between;border-bottom:1px solid #bdc9da;padding-bottom:20px}h1{font-size:clamp(28px,3.4vw,58px);font-weight:500;letter-spacing:-1.7px;max-width:1000px;margin:3vh 0;color:#103f86;line-height:1.08}.content{position:relative;z-index:1;columns:2;column-gap:5vw;max-height:66vh;overflow:auto;padding:20px 25px;border-left:3px solid #3478eb;background:#ffffffa8;border-radius:0 18px 18px 0}.content p{font-size:clamp(14px,1.33vw,23px);line-height:1.32;margin:0 0 9px;break-inside:avoid}.slide:first-child h1{font-size:clamp(42px,6vw,100px);max-width:950px;margin-top:10vh}.slide:first-child .content{columns:1;max-width:720px}.slide:last-child .content{columns:2;max-width:900px}.orb{position:absolute;right:-100px;bottom:-160px;width:450px;height:450px;border:1px solid #9fbae0;border-radius:50%;box-shadow:0 0 0 40px #bbcef21c,0 0 0 80px #bbcef211;pointer-events:none}nav{position:fixed;bottom:25px;left:7vw;right:7vw;display:flex;align-items:center;gap:12px;z-index:10}button{border:1px solid #b5c7df;border-radius:30px;background:#ffffffd9;color:#174987;padding:10px 19px;cursor:pointer;font:inherit}button:hover{background:#175dd3;color:white}#count{margin-right:auto;font-size:13px;letter-spacing:2px}#progress{position:fixed;bottom:0;height:4px;background:#246ce0;transition:width .6s;z-index:20}@media(max-width:700px){.content{columns:1;max-height:65vh}.eyebrow{font-size:9px;letter-spacing:1px}nav{bottom:15px}button{padding:8px 12px}}@media(prefers-reduced-motion:reduce){*{transition:none!important}}@media print{body{overflow:visible}.slide{position:relative;opacity:1;transform:none;height:100vh;break-after:page}nav,#progress{display:none}}'''
js='''const slides=[...document.querySelectorAll('.slide')];let i=0;function show(n){i=Math.max(0,Math.min(slides.length-1,n));slides.forEach((s,k)=>s.classList.toggle('active',k===i));document.querySelector('#count').textContent=String(i+1).padStart(2,'0')+' / '+slides.length;document.querySelector('#progress').style.width=((i+1)/slides.length*100)+'%'}document.querySelector('#prev').onclick=()=>show(i-1);document.querySelector('#next').onclick=()=>show(i+1);document.querySelector('#full').onclick=()=>document.fullscreenElement?document.exitFullscreen():document.documentElement.requestFullscreen();document.addEventListener('keydown',e=>{if(['ArrowRight','PageDown',' '].includes(e.key)){e.preventDefault();show(i+1)}if(['ArrowLeft','PageUp'].includes(e.key))show(i-1);if(e.key==='Home')show(0);if(e.key==='End')show(slides.length-1)});let start=0;document.addEventListener('touchstart',e=>start=e.changedTouches[0].clientX);document.addEventListener('touchend',e=>{let delta=e.changedTouches[0].clientX-start;if(Math.abs(delta)>60)show(i+(delta<0?1:-1))});show(0);'''
(p/'territory-automation.html').write_text('<!doctype html><html lang="ru"><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Territory Automation — Спринт 3</title><style>'+css+'</style><body>'+''.join(sections)+'<nav><span id="count"></span><button id="prev" aria-label="Предыдущий слайд">←</button><button id="next" aria-label="Следующий слайд">→</button><button id="full">Полный экран</button></nav><div id="progress"></div><script>'+js+'</script></body></html>',encoding='utf-8')
print('Created 9 slides; source pages:',pages)
